// Client Script

frappe.ui.form.on('Demooooo', {
    refresh(frm) {
        calc_total_distance(frm);
        check_charges(frm);          // make sure charges are sane on load
    },

    child_table_add(frm) {
        calc_total_distance(frm);
    },

    child_table_remove(frm) {
        calc_total_distance(frm);
    },

    // fire whenever either charge field changes
    waiting_charges(frm) {
        check_charges(frm);
    },

    holting_charges(frm) {
        check_charges(frm);
    }
});

frappe.ui.form.on('child_table', {
    distance(frm, cdt, cdn) {
        calc_total_distance(frm);
    }
});

// ---------- helpers ----------

// sum Distance column in the child table
function calc_total_distance(frm) {
    const total = (frm.doc.child_table || []).reduce(
        (sum, row) => sum + (parseFloat(row.distance) || 0),
        0
    );
    frm.set_value('total_distance', total);
}

// enforce “only one charge” rule
function check_charges(frm) {
    const waiting = parseFloat(frm.doc.waiting_charges) || 0;
    const holting = parseFloat(frm.doc.holting_charges) || 0;

    if (waiting && holting) {
        // both entered – not allowed
        frappe.msgprint({
            title: __('Only One Charge Allowed'),
            indicator: 'red',
            message: __('Enter a value in either <b>Waiting Charges</b> or <b>Holting Charges</b>, not both. <br>Waiting Charges has been reset to 0.')
        });
        frm.set_value('waiting_charges', 0);   // keep holting_charges, zero waiting_charges
    } else if (waiting && !holting) {
        // waiting entered alone – zero holting
        frm.set_value('holting_charges', 0);
    } else if (holting && !waiting) {
        // holting entered alone – zero waiting
        frm.set_value('waiting_charges', 0);
    }
}

