frappe.ui.form.on('Work Team', {
    team_leader: function(frm) {
        if (!frm.doc.team_leader) return;

        // Check if team leader is already in members list with complete details
        if (is_team_leader_complete(frm)) {
            return; // Skip if already properly added
        }

        // Get user details
        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "User",
                name: frm.doc.team_leader,
                fieldname: ["email", "full_name"]
            },
            callback: function(user_response) {
                if (!user_response.message) return;

                let user_email = user_response.message.email;
                let user_full_name = user_response.message.full_name;

                // Find matching employee
                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Employee",
                        filters: {
                            "user_id": frm.doc.team_leader
                        },
                        fields: ["name", "employee_name", "custom_email_address"]
                    },
                    callback: function(employee_response) {
                        if (!employee_response.message || employee_response.message.length === 0) return;

                        let employee = employee_response.message[0];
                        
                        // Add to members list with all details
                        let child = frappe.model.add_child(frm.doc, "Team Members List", "team_members_list");
                        frappe.model.set_value(child.doctype, child.name, {
                            "employee_id": employee.name,
                            "full_name": user_full_name + " (TL)" || employee.employee_name + " (TL)",
                            "email": user_email || employee.custom_email_address
                        });
                        frm.refresh_field("team_members_list");
                    }
                });
            }
        });
    },
    
    validate: function(frm) {
        if (frm.doc.team_leader && frm.doc.team_members_list) {
            // Skip validation if team leader is already complete
            if (is_team_leader_complete(frm)) return;
            
            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Employee",
                    fieldname: "name",
                    filters: {
                        "user_id": frm.doc.team_leader
                    }
                },
                async: false,
                callback: function(r) {
                    if (r.message && !frm.doc.team_members_list.some(member => 
                        member.employee_id === r.message.name
                    )) {
                        frappe.validated = false;
                        frappe.msgprint({
                            title: __('Validation Error'),
                            message: __('Team leader must be in members list'),
                            indicator: 'red'
                        });
                    }
                }
            });
        }
    }
});

// Helper function to check if team leader is already properly added
function is_team_leader_complete(frm) {
    if (!frm.doc.team_leader || !frm.doc.team_members_list) return false;
    
    // Get employee ID for the team leader
    let employee_id = null;
    frappe.call({
        method: "frappe.client.get_value",
        args: {
            doctype: "Employee",
            fieldname: "name",
            filters: {
                "user_id": frm.doc.team_leader
            }
        },
        async: false,
        callback: function(r) {
            if (r.message) employee_id = r.message.name;
        }
    });
    
    if (!employee_id) return false;
    
    // Check if exists with complete details
    return frm.doc.team_members_list.some(member => 
        member.employee_id === employee_id &&
        member.full_name &&
        member.email
    );
}

