frappe.ui.form.on('Project Setup', {
    after_save(frm) {
        frm.reload_doc();  // reloads the full form to get fresh DB values
    },

    before_submit(frm) {
        // Set current date as completion date
        const today = frappe.datetime.now_date();
        frm.set_value('completion_date', today);

        // Set completion month based on today's date
        const month = frappe.datetime.str_to_obj(today).toLocaleString('default', { month: 'long' });
        frm.set_value('completion_month', month);
    },

    project__object_size_in_hecter: function(frm) {
        set_price_per_hecter(frm);
    },

    project__object_price_per_hecter: function(frm) {
        set_price_per_hecter(frm);
    }
});

function set_price_per_hecter(frm) {
    let price = 0;
    if (frm.doc.task === "Forest Clearing" && frm.doc.clearing_cost) {
        price = frm.doc.project__object_size_in_hecter * frm.doc.clearing_cost;
        frm.set_value("object_compensation", price);
        frm.set_df_property("object_compensation", "read_only", 1);
    } else if (frm.doc.task === "Forest Planting" && frm.doc.planting_cost) {
        price = frm.doc.project__object_size_in_hecter * frm.doc.planting_cost;
        frm.set_value("object_compensation", price);
        frm.set_df_property("object_compensation", "read_only", 1);
    } else {
        frm.set_value("object_compensation", price);
        frm.set_df_property("object_compensation", "read_only", 0);
    }
}

