// Function to fetch emergency contact number
function fetch_emergency_contact_number(frm) {
    if (frm.doc.job_applicant) {
        console.log('Fetching emergency contact for job_applicant:', frm.doc.job_applicant);

        frappe.db.get_value('Job Applicant', frm.doc.job_applicant, [
            'custom_emergency_contact_mobile_phone_number'
        ]).then(r => {
            console.log('Emergency contact response:', r);

            if (r.message && r.message.custom_emergency_contact_mobile_phone_number) {
                console.log('Setting emergency contact number:', r.message.custom_emergency_contact_mobile_phone_number);

                frm.set_value('custom_emergency_contact_mobile_phone_number',
                    r.message.custom_emergency_contact_mobile_phone_number
                );
            } else {
                console.log('No emergency contact number found for job_applicant:', frm.doc.job_applicant);
                // Clear the field if no data found
                frm.set_value('custom_emergency_contact_mobile_phone_number', '');
            }
        }).catch(err => {
            console.error('Error fetching emergency contact number:', err);
            frappe.msgprint({
                title: __('Error'),
                message: __('Could not fetch emergency contact number from Job Applicant'),
                indicator: 'red'
            });
        });
    } else {
        // Clear the field if no job_applicant selected
        frm.set_value('custom_emergency_contact_mobile_phone_number', '');
    }
}

