frappe.ui.form.on('Net Compensation', {
    refresh: function(frm) {
        // Add button to calculate net compensation
        frm.add_custom_button(__('Calculate Net Compensation'), function() {
            frm.events.calculate_net_compensation(frm);
        }).addClass('btn-primary');
    },

    work_team: function(frm) {
        // Clear compensation table when work team changes
        frm.set_value('compensation', []);
    },

    calculate_net_compensation: function(frm) {
        if (!frm.doc.work_team || !frm.doc.year || !frm.doc.month) {
            frappe.msgprint(__('Please select Work Team, Year, and Month first.'));
            return;
        }

        frappe.call({
            method: 'contract_management.contract_management.doctype.net_compensation.net_compensation.get_employees_by_work_team',
            args: {
                work_team: frm.doc.work_team
            },
            callback: function(r) {
                if (r.message) {
                    frm.events.fetch_employee_data(frm, r.message);
                }
            }
        });
    },


    
    





    fetch_employee_data: function(frm, employees) {
    let compensation_items = [];
    let promises = [];

    employees.forEach(employee => {
        promises.push(new Promise((resolve) => {
            frappe.call({
                method: 'contract_management.contract_management.doctype.net_compensation.net_compensation.get_employee_attendance',
                args: {
                    employee: employee.employee,
                    month: frm.doc.month,
                    year: frm.doc.year
                },
                callback: function(r) {
                    if (r.message) {
                        compensation_items.push({
                            employee: employee.employee,
                            attendance: r.message.attendance,
                            total_hours: r.message.total_hours,  
                            daily_allowance_rate_sek: r.message.daily_allowance_rate,
                            daily_allowance_total_sek: r.message.daily_allowance_total_sek,
                            total_net_compensation: r.message.total_net_compensation,
                            net_compensation_excluding_daily_allowance: r.message.net_compensation_excluding_daily_allowance,
                            piecework_compensation: r.message.piecework_compensation,
                            holiday_compensation_13: r.message.holiday_compensation_13,
                            reduction_in_working_hours_362: r.message.reduction_in_working_hours_362,
                            gross_salary_total: r.message.gross_salary_total,
                            tax_amount: r.message.tax_amount
                        });
                    }
                    resolve();
                }
            });
        }));
    });

    Promise.all(promises).then(() => {
        frm.set_value('compensation', compensation_items);
        frm.refresh_field('compensation');
    });
}



});

