frappe.ui.form.on('Total Compensation', {
    year: function(frm) {
        if (frm.doc.year) {
            frappe.db.get_doc("Fiscal Year", frm.doc.year)
                .then(fy => {
                    let start = frappe.datetime.str_to_obj(fy.year_start_date);
                    let end = frappe.datetime.str_to_obj(fy.year_end_date);

                    let months = [];
                    let current = new Date(start);

                    while (current <= end) {
                        let month_name = frappe.datetime.month_name(current.getMonth() + 1);
                        if (!months.includes(month_name)) {
                            months.push(month_name);
                        }
                        current.setMonth(current.getMonth() + 1);
                    }

                    // set month options
                    frm.set_df_property("month", "options", ["\n"].concat(months).join("\n"));
                    frm.refresh_field("month");
                });
        }
    }
});

